class ThemeBootstrapper{static STORAGE_KEY="vd_theme";static VALID_THEMES=["light","dark"];static DEFAULT_THEME="light";static apply(t=document,e=localStorage,r=window){const a=this.resolveTheme(e,r);return t.documentElement.setAttribute("data-theme",a),a}static resolveTheme(t=localStorage,e=window){const r=this.readSaved(t);if(r)return r;return"function"==typeof e.matchMedia&&e.matchMedia("(prefers-color-scheme: dark)").matches?"dark":this.DEFAULT_THEME}static readSaved(t=localStorage){try{const e=t.getItem(this.STORAGE_KEY);if(!e)return null;let r;try{r=JSON.parse(e)}catch{r=e}return this.VALID_THEMES.includes(r)?r:null}catch{return null}}}ThemeBootstrapper.apply(),"undefined"!=typeof window&&(window.ThemeBootstrapper=ThemeBootstrapper);